def f_prem(x):
    d = 2
    ch = ""
    while x != 1:
        if x % d == 0:
            ch =  ch +"*" + str(d)
            x = x // d
        else:
            d += 1
    
    return ch[1:]


def pgcd(a, b):
    fpa = f_prem(a)
    fpb = f_prem(b)
    print(fpa)
    print(fpb)
    i = 0
    j = 0
    p = 1
    while i < len(fpa) and j < len(fpb):
        if fpa[i] == "*":
            i += 1
        if fpb[i] == "*":
            j += 1
        if fpa[i] == fpb[j]:
            p = p * int(fpa[i])
            i += 1
            j += 1
        elif fpa[i] < fpb[j]:
            i += 1
        else:
            j += 1
    return p


